"""
Adapter contract validation and profile constants.

This module defines:
  - The canonical set of DEPLOYMENT_PROFILE values.
  - The canonical set of adapter port names.
  - Validation helpers that ensure a registry satisfies all port contracts.
"""

from __future__ import annotations

from typing import Any, Type

from shared.adapters.ports import (
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
)

# ── Canonical profiles ──────────────────────────────────────────────
VALID_PROFILES: frozenset[str] = frozenset({"aws", "onprem"})

# ── Port name → ABC mapping (single source of truth) ───────────────
PORT_CONTRACTS: dict[str, Type[Any]] = {
    "object_storage": ObjectStoragePort,
    "queue": QueuePort,
    "eventing": EventingPort,
    "secrets": SecretsPort,
    "log_sink": LogSinkPort,
}


class ProfileValidationError(Exception):
    """Raised when a profile value is not in the canonical set."""


class AdapterContractViolation(Exception):
    """Raised when a registry does not satisfy all port contracts."""


def validate_profile(profile: str) -> str:
    """Return the normalised profile or raise ProfileValidationError."""
    normalised = profile.strip().lower()
    if normalised not in VALID_PROFILES:
        raise ProfileValidationError(
            f"Invalid DEPLOYMENT_PROFILE={profile!r}. "
            f"Must be one of {sorted(VALID_PROFILES)}."
        )
    return normalised


def validate_adapter_instance(port_name: str, instance: Any) -> None:
    """Raise AdapterContractViolation if *instance* does not implement the expected port."""
    expected_type = PORT_CONTRACTS.get(port_name)
    if expected_type is None:
        raise AdapterContractViolation(f"Unknown port name: {port_name!r}")
    if not isinstance(instance, expected_type):
        raise AdapterContractViolation(
            f"Adapter for port {port_name!r} must be an instance of "
            f"{expected_type.__name__}, got {type(instance).__name__}."
        )


def validate_registry_complete(adapters: dict[str, Any]) -> None:
    """Raise AdapterContractViolation if any required port is missing or wrong type."""
    for port_name, expected_type in PORT_CONTRACTS.items():
        if port_name not in adapters:
            raise AdapterContractViolation(f"Missing adapter for port {port_name!r}.")
        validate_adapter_instance(port_name, adapters[port_name])

