"""
AWS S3 adapter for ObjectStoragePort.

Uses boto3 with endpoint_url override support for LocalStack compatibility.
"""

from __future__ import annotations

import os
from typing import Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import ObjectStoragePort


class S3ObjectStorage(ObjectStoragePort):
    """S3-backed object storage adapter."""

    def __init__(self, endpoint_url: Optional[str] = None, region: Optional[str] = None) -> None:
        self._endpoint_url = endpoint_url or os.environ.get("AWS_ENDPOINT_URL") or os.environ.get("S3_ENDPOINT_URL")
        self._region = region or os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
        self._client = boto3.client(
            "s3",
            endpoint_url=self._endpoint_url,
            region_name=self._region,
        )

    def ensure_bucket(self, bucket: str) -> None:
        try:
            self._client.head_bucket(Bucket=bucket)
        except ClientError:
            create_kwargs: dict = {"Bucket": bucket}
            if self._region and self._region != "us-east-1":
                create_kwargs["CreateBucketConfiguration"] = {
                    "LocationConstraint": self._region,
                }
            self._client.create_bucket(**create_kwargs)

    def put_object(self, bucket: str, key: str, data: bytes, metadata: Optional[dict[str, str]] = None) -> None:
        kwargs: dict = {"Bucket": bucket, "Key": key, "Body": data}
        if metadata:
            kwargs["Metadata"] = metadata
        self._client.put_object(**kwargs)

    def get_object(self, bucket: str, key: str) -> bytes:
        try:
            resp = self._client.get_object(Bucket=bucket, Key=key)
            return resp["Body"].read()
        except ClientError as exc:
            if exc.response["Error"]["Code"] in ("NoSuchKey", "404"):
                raise KeyError(f"{bucket}/{key}") from exc
            raise

    def delete_object(self, bucket: str, key: str) -> None:
        self._client.delete_object(Bucket=bucket, Key=key)

    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        resp = self._client.list_objects_v2(Bucket=bucket, Prefix=prefix)
        return [obj["Key"] for obj in resp.get("Contents", [])]

