"""
AWS SQS adapter for QueuePort.
"""

from __future__ import annotations

import os
from typing import Any, Optional

import boto3

from shared.adapters.ports import QueuePort


class SQSQueue(QueuePort):
    """SQS-backed queue adapter."""

    def __init__(self, endpoint_url: Optional[str] = None, region: Optional[str] = None) -> None:
        self._endpoint_url = endpoint_url or os.environ.get("AWS_ENDPOINT_URL") or os.environ.get("SQS_ENDPOINT_URL")
        self._region = region or os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
        self._client = boto3.client(
            "sqs",
            endpoint_url=self._endpoint_url,
            region_name=self._region,
        )
        self._queue_url_cache: dict[str, str] = {}

    def _queue_url(self, queue_name: str) -> str:
        if queue_name not in self._queue_url_cache:
            resp = self._client.get_queue_url(QueueName=queue_name)
            self._queue_url_cache[queue_name] = resp["QueueUrl"]
        return self._queue_url_cache[queue_name]

    def ensure_queue(self, queue_name: str) -> None:
        resp = self._client.create_queue(QueueName=queue_name)
        self._queue_url_cache[queue_name] = resp["QueueUrl"]

    def send_message(self, queue_name: str, body: str, attributes: Optional[dict[str, str]] = None) -> str:
        kwargs: dict[str, Any] = {
            "QueueUrl": self._queue_url(queue_name),
            "MessageBody": body,
        }
        if attributes:
            kwargs["MessageAttributes"] = {
                k: {"DataType": "String", "StringValue": v} for k, v in attributes.items()
            }
        resp = self._client.send_message(**kwargs)
        return resp["MessageId"]

    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]:
        resp = self._client.receive_message(
            QueueUrl=self._queue_url(queue_name),
            MaxNumberOfMessages=max_messages,
            WaitTimeSeconds=wait_seconds,
        )
        return [
            {
                "message_id": m["MessageId"],
                "body": m["Body"],
                "receipt_handle": m["ReceiptHandle"],
            }
            for m in resp.get("Messages", [])
        ]

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        self._client.delete_message(
            QueueUrl=self._queue_url(queue_name),
            ReceiptHandle=receipt_handle,
        )

