"""
AWS CloudWatch Logs adapter for LogSinkPort.
"""

from __future__ import annotations

import json
import os
import time
from typing import Any, Optional

import boto3

from shared.adapters.ports import LogSinkPort


class CloudWatchLogSink(LogSinkPort):
    """CloudWatch Logs-backed log sink adapter."""

    def __init__(
        self,
        log_group: Optional[str] = None,
        log_stream: Optional[str] = None,
        endpoint_url: Optional[str] = None,
        region: Optional[str] = None,
    ) -> None:
        self._endpoint_url = endpoint_url or os.environ.get("AWS_ENDPOINT_URL") or os.environ.get("LOGS_ENDPOINT_URL")
        self._region = region or os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
        self._log_group = log_group or os.environ.get("LOG_GROUP", "/app/default")
        self._log_stream = log_stream or os.environ.get("LOG_STREAM", "default-stream")
        self._client = boto3.client(
            "logs",
            endpoint_url=self._endpoint_url,
            region_name=self._region,
        )
        self._sequence_token: Optional[str] = None
        self._ensured = False

    def _ensure(self) -> None:
        if self._ensured:
            return
        try:
            self._client.create_log_group(logGroupName=self._log_group)
        except self._client.exceptions.ResourceAlreadyExistsException:
            pass
        try:
            self._client.create_log_stream(
                logGroupName=self._log_group,
                logStreamName=self._log_stream,
            )
        except self._client.exceptions.ResourceAlreadyExistsException:
            pass
        self._ensured = True

    def emit(self, log_entry: dict[str, Any]) -> None:
        self._ensure()
        kwargs: dict[str, Any] = {
            "logGroupName": self._log_group,
            "logStreamName": self._log_stream,
            "logEvents": [
                {
                    "timestamp": int(time.time() * 1000),
                    "message": json.dumps(log_entry),
                }
            ],
        }
        if self._sequence_token:
            kwargs["sequenceToken"] = self._sequence_token
        resp = self._client.put_log_events(**kwargs)
        self._sequence_token = resp.get("nextSequenceToken")

