"""
On-prem MinIO adapter for ObjectStoragePort.

Uses the minio Python SDK. Endpoint is configurable via env vars
for both production MinIO clusters and local dev containers.
"""

from __future__ import annotations

import io
import os
from typing import Optional

from minio import Minio
from minio.error import S3Error

from shared.adapters.ports import ObjectStoragePort


class MinioObjectStorage(ObjectStoragePort):
    """MinIO-backed object storage adapter."""

    def __init__(
        self,
        endpoint: Optional[str] = None,
        access_key: Optional[str] = None,
        secret_key: Optional[str] = None,
        secure: Optional[bool] = None,
    ) -> None:
        self._endpoint = endpoint or os.environ.get("MINIO_ENDPOINT", "localhost:9000")
        self._access_key = access_key or os.environ.get("MINIO_ACCESS_KEY", "minioadmin")
        self._secret_key = secret_key or os.environ.get("MINIO_SECRET_KEY", "minioadmin")
        _secure = secure if secure is not None else os.environ.get("MINIO_SECURE", "false").lower() == "true"
        self._client = Minio(
            self._endpoint,
            access_key=self._access_key,
            secret_key=self._secret_key,
            secure=_secure,
        )

    def ensure_bucket(self, bucket: str) -> None:
        if not self._client.bucket_exists(bucket):
            self._client.make_bucket(bucket)

    def put_object(self, bucket: str, key: str, data: bytes, metadata: Optional[dict[str, str]] = None) -> None:
        self._client.put_object(
            bucket,
            key,
            io.BytesIO(data),
            length=len(data),
            metadata=metadata,
        )

    def get_object(self, bucket: str, key: str) -> bytes:
        try:
            resp = self._client.get_object(bucket, key)
            return resp.read()
        except S3Error as exc:
            if exc.code == "NoSuchKey":
                raise KeyError(f"{bucket}/{key}") from exc
            raise
        finally:
            try:
                resp.close()  # type: ignore[possibly-undefined]
                resp.release_conn()  # type: ignore[possibly-undefined]
            except Exception:
                pass

    def delete_object(self, bucket: str, key: str) -> None:
        self._client.remove_object(bucket, key)

    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        return [obj.object_name for obj in self._client.list_objects(bucket, prefix=prefix) if obj.object_name]

