"""
On-prem Redis-backed adapter for QueuePort.

Uses Redis lists as a simple reliable queue.
"""

from __future__ import annotations

import json
import os
import uuid
from typing import Any, Optional

import redis

from shared.adapters.ports import QueuePort


class RedisQueue(QueuePort):
    """Redis list-backed queue adapter."""

    def __init__(self, redis_url: Optional[str] = None) -> None:
        self._redis_url = redis_url or os.environ.get("REDIS_URL", "redis://localhost:6379/0")
        self._client = redis.Redis.from_url(self._redis_url, decode_responses=True)

    def ensure_queue(self, queue_name: str) -> None:
        # Redis lists are created implicitly; this is a no-op for compatibility.
        pass

    def send_message(self, queue_name: str, body: str, attributes: Optional[dict[str, str]] = None) -> str:
        message_id = uuid.uuid4().hex
        envelope = json.dumps({
            "message_id": message_id,
            "body": body,
            "attributes": attributes or {},
        })
        self._client.lpush(queue_name, envelope)
        return message_id

    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]:
        results: list[dict[str, Any]] = []
        for _ in range(max_messages):
            if wait_seconds > 0:
                item = self._client.brpop(queue_name, timeout=wait_seconds)
                raw = item[1] if item else None
            else:
                raw = self._client.rpop(queue_name)
            if raw is None:
                break
            envelope = json.loads(raw)
            results.append({
                "message_id": envelope["message_id"],
                "body": envelope["body"],
                "receipt_handle": envelope["message_id"],  # for Redis, id == handle
            })
        return results

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        # In this Redis-list model, messages are already removed on receive.
        # This is a no-op for interface parity.
        pass

