"""
On-prem file-based adapter for SecretsPort.

Stores secrets as individual files under a configurable directory.
Suitable for on-prem deployments using mounted volumes or config-management
tools that render secrets to disk.
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Optional

from shared.adapters.ports import SecretsPort


class FileSecrets(SecretsPort):
    """File-system-backed secrets adapter."""

    def __init__(self, secrets_dir: Optional[str] = None) -> None:
        self._secrets_dir = Path(
            secrets_dir or os.environ.get("SECRETS_DIR", "/run/secrets")
        )

    def get_secret(self, secret_id: str) -> str:
        path = self._secrets_dir / secret_id
        if not path.is_file():
            raise KeyError(secret_id)
        return path.read_text().strip()

    def put_secret(self, secret_id: str, value: str) -> None:
        self._secrets_dir.mkdir(parents=True, exist_ok=True)
        path = self._secrets_dir / secret_id
        path.write_text(value)

