"""
On-prem file-based adapter for LogSinkPort.

Appends JSON-line entries to a configurable log file.
"""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any, Optional

from shared.adapters.ports import LogSinkPort


class FileLogSink(LogSinkPort):
    """File-backed structured log sink adapter."""

    def __init__(self, log_path: Optional[str] = None) -> None:
        self._log_path = Path(
            log_path or os.environ.get("LOG_SINK_PATH", "/var/log/app/structured.jsonl")
        )

    def emit(self, log_entry: dict[str, Any]) -> None:
        self._log_path.parent.mkdir(parents=True, exist_ok=True)
        with self._log_path.open("a") as f:
            f.write(json.dumps(log_entry) + "\n")

