def _localstack_available() -> bool:
    """Check if LocalStack S3 endpoint is reachable."""
    import socket
    host = os.environ.get("LOCALSTACK_HOST", "localhost")
    port = int(os.environ.get("LOCALSTACK_PORT", "4566"))
    try:
        with socket.create_connection((host, port), timeout=2):
            return True
    except OSError:
        return False


def _minio_available() -> bool:
    """Check if MinIO endpoint is reachable."""
    import socket
    endpoint = os.environ.get("MINIO_ENDPOINT", "localhost:9000")
    host, _, port_str = endpoint.partition(":")
    port = int(port_str) if port_str else 9000
    try:
        with socket.create_connection((host, port), timeout=2):
            return True
    except OSError:
        return False


